import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import { generateKeyPairSync, randomUUID } from "node:crypto";
import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { SqliteDurableLedger } from "../persistence/sqlite-ledger.js";
import { LocalProposalStore } from "../proposals/local-proposal-store.js";
import type { StoredProposal } from "../proposals/contracts.js";
import { SyntheticInstructionDraftingAgent } from "../ai/synthetic-agent.js";
import { OllamaInstructionDraftingAgent, loadOllamaConfig } from "../ai/ollama-agent.js";
import { DemoWorkflowService } from "../services/demo-workflow-service.js";
import { PayPalSandboxOrdersAdapter, PayPalSandboxPaymentLinksAdapter } from "../adapters/paypal-sandbox.js";
import { loadStage1Config } from "../config/config.js";
import { PayPalPaymentLinkCollectionService } from "../services/paypal-payment-link-service.js";
import { PayPalOrdersPayLinkService } from "../services/paypal-orders-paylink-service.js";
import { TransactionStatusService } from "../services/transaction-status-service.js";
import type { Stage1Persistence } from "../persistence/contracts.js";

type Json = Record<string, unknown>;
type Mode = "synthetic" | "ollama";

/** Local-only Stage 3B demo. The switchboard is a view over the existing ledger and workflow services. */
export function createStage2aDemoServer(dataRoot = join(process.cwd(), ".hbiepa-data"), environment: NodeJS.ProcessEnv = process.env): Server {
  mkdirSync(dataRoot, { recursive: true });
  const keys = demoKeys(dataRoot); const ledger = new SqliteDurableLedger(join(dataRoot, "hbiepa-stage2a.sqlite")); const store = new LocalProposalStore(join(dataRoot, "stage2a-proposals.json"));
  const offline = new DemoWorkflowService(ledger, store, new SyntheticInstructionDraftingAgent(), keys);
  const transactionStatus = new TransactionStatusService(ledger, store, keys.publicKeyPem);
  const ollama = () => { const config = loadOllamaConfig(environment); if (!config) throw new Error("OLLAMA_NOT_CONFIGURED: choose Offline Demo or set HBIEPA_AI_PROVIDER=ollama"); return new DemoWorkflowService(ledger, store, new OllamaInstructionDraftingAgent(config), keys); };
  const paymentLinks = () => {
    const config = loadStage1Config(environment);
    if (!config.paypalClientId || !config.paypalClientSecret) throw new Error("PAYPAL_SANDBOX_CREDENTIALS_NOT_CONFIGURED");
    return new PayPalPaymentLinkCollectionService(ledger, store, keys.publicKeyPem, new PayPalSandboxPaymentLinksAdapter(new PayPalSandboxOrdersAdapter({ clientId: config.paypalClientId, clientSecret: config.paypalClientSecret })), config.paypalMerchantId);
  };
  const sandboxPreflight = async () => {
    const config = loadStage1Config(environment);
    if (!config.paypalClientId || !config.paypalClientSecret || !config.paypalMerchantId) throw new Error("PAYPAL_SANDBOX_CREDENTIALS_OR_MERCHANT_NOT_CONFIGURED");
    return new PayPalSandboxOrdersAdapter({ clientId: config.paypalClientId, clientSecret: config.paypalClientSecret }).preflight({ expectedMerchantId: config.paypalMerchantId });
  };
  const ordersPayLink = () => {
    const config = loadStage1Config(environment);
    if (!config.paypalClientId || !config.paypalClientSecret || !config.paypalMerchantId) throw new Error("PAYPAL_SANDBOX_CREDENTIALS_OR_MERCHANT_NOT_CONFIGURED");
    const paypal = new PayPalSandboxOrdersAdapter({ clientId: config.paypalClientId, clientSecret: config.paypalClientSecret });
    return new PayPalOrdersPayLinkService(ledger, store, keys.publicKeyPem, paypal, config.paypalMerchantId, async () => paypal.preflight({ expectedMerchantId: config.paypalMerchantId! }));
  };
  return createServer(async (request, response) => {
    try {
      const url = new URL(request.url ?? "/", "http://127.0.0.1");
      const publicMatch = request.method === "GET" ? url.pathname.match(/^\/pay\/([A-Za-z0-9_-]{43})$/) : undefined;
      const checkoutMatch = request.method === "GET" ? url.pathname.match(/^\/pay\/([A-Za-z0-9_-]{43})\/checkout$/) : undefined;
      if (publicMatch) return paymentPage(response, await ordersPayLink().publicSession(publicMatch[1]));
      if (checkoutMatch) { response.writeHead(302, { Location: await ordersPayLink().checkoutUrl(checkoutMatch[1]), "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" }); response.end(); return; }
      if (request.method === "GET" && url.pathname === "/") return html(response);
      if (request.method === "GET" && url.pathname === "/api/status") return send(response, 200, status(environment));
      if (request.method === "GET" && url.pathname === "/api/paypal-sandbox-preflight") return send(response, 200, await sandboxPreflight());
      if (request.method === "GET" && url.pathname === "/api/historical-evidence") return send(response, 200, await historicalEvidence(ledger));
      if (request.method === "GET" && url.pathname === "/api/proposals") return send(response, 200, { proposals: await store.list() });
      if (request.method === "GET" && url.pathname === "/api/recovered-instructions") return send(response, 200, { instructions: await recoveredInstructionInventory(ledger, store) });
      const statusMatch = request.method === "GET" ? url.pathname.match(/^\/api\/proposals\/([^/]+)\/transaction-status$/) : undefined;
      if (statusMatch) return send(response, 200, await transactionStatus.forProposal(decodeURIComponent(statusMatch[1])));
      const paymentSessionMatch = request.method === "GET" ? url.pathname.match(/^\/api\/proposals\/([^/]+)\/orders-payment-session$/) : undefined;
      if (paymentSessionMatch) return send(response, 200, await ordersPayLink().inspect(decodeURIComponent(paymentSessionMatch[1])));
      const input = request.method === "POST" ? await body(request) : undefined;
      const service = mode(input) === "ollama" ? ollama() : offline;
      if (request.method === "POST" && url.pathname === "/api/switchboard/generate") return send(response, 201, await service.generate(buildSwitchboardInstruction(input)));
      if (request.method === "POST" && url.pathname === "/api/generate") return send(response, 201, await service.generate(text(input, "instruction")));
      if (request.method === "POST" && url.pathname.endsWith("/approve")) return send(response, 200, await offline.approve(id(url.pathname), optional(input, "operatorId") ?? "demo-operator"));
      if (request.method === "POST" && url.pathname.endsWith("/reject")) return send(response, 200, await offline.reject(id(url.pathname), optional(input, "reason") ?? "Operator rejected proposal"));
      if (request.method === "POST" && url.pathname.endsWith("/amend")) return send(response, 201, await service.amendFromInstruction(id(url.pathname), text(input, "instruction")));
      if (request.method === "POST" && url.pathname.endsWith("/sign")) return send(response, 200, await offline.sign(id(url.pathname)));
      if (request.method === "POST" && url.pathname.endsWith("/payment-link")) return send(response, 201, await paymentLinks().create(id(url.pathname), paymentLinkReturnUrl(environment)));
      if (request.method === "POST" && url.pathname.endsWith("/verify-payment-link")) return send(response, 200, await paymentLinks().verify(id(url.pathname)));
      if (request.method === "POST" && url.pathname.endsWith("/orders-payment-session")) return send(response, 201, await ordersPayLink().create(id(url.pathname), paymentLinkReturnUrl(environment), paymentLinkCancelUrl(environment)));
      if (request.method === "POST" && url.pathname.endsWith("/verify-orders-payment")) return send(response, 200, await ordersPayLink().verifyAndCapture(id(url.pathname)));
      if (request.method === "POST" && url.pathname.endsWith("/authorise-orders-simulation")) return send(response, 200, await ordersPayLink().authoriseSimulation(id(url.pathname)));
      if (request.method === "POST" && url.pathname.endsWith("/execute-orders-simulation")) return send(response, 200, await ordersPayLink().executeSimulation(id(url.pathname)));
      if (request.method === "POST" && url.pathname.endsWith("/run")) return send(response, 200, await offline.runSyntheticDemo(id(url.pathname)));
      if (request.method === "POST" && url.pathname.endsWith("/mismatch")) return send(response, 200, { outcome: await offline.runPaymentMismatch(id(url.pathname)) });
      if (request.method === "POST" && url.pathname === "/api/reset") return send(response, 200, { sessionId: `synthetic-demo-${randomUUID()}`, message: "Fresh synthetic identity created; immutable historical records were retained." });
      send(response, 404, { error: "NOT_FOUND" });
    } catch (error) { send(response, 400, { error: safe(error) }); }
  });
}

export function listenLoopbackDemo(server: Server, port: number): Promise<void> {
  if (!Number.isInteger(port) || port < 1024 || port > 65535) return Promise.reject(new Error("HBIEPA_DEMO_PORT must be 1024-65535"));
  return new Promise((resolve, reject) => { const failed = (error: NodeJS.ErrnoException) => reject(error.code === "EADDRINUSE" ? new Error(`DEMO_PORT_IN_USE: http://127.0.0.1:${port} is in use. Stop the existing HBIEPA demo or set HBIEPA_DEMO_PORT.`) : new Error("DEMO_SERVER_START_FAILED")); server.once("error", failed); server.listen(port, "127.0.0.1", () => { server.off("error", failed); resolve(); }); });
}

function demoKeys(root: string) { const privatePath = join(root, "stage2a-demo-private.pem"); const publicPath = join(root, "stage2a-demo-public.pem"); if (!existsSync(privatePath) || !existsSync(publicPath)) { const pair = generateKeyPairSync("ed25519"); writeFileSync(privatePath, pair.privateKey.export({ type: "pkcs8", format: "pem" }), { mode: 0o600 }); writeFileSync(publicPath, pair.publicKey.export({ type: "spki", format: "pem" }), { mode: 0o600 }); } return { privateKeyPem: readFileSync(privatePath, "utf8"), publicKeyPem: readFileSync(publicPath, "utf8"), keyId: "stage2a-local-demo-key" }; }
function status(env: NodeJS.ProcessEnv) { try { const config = loadOllamaConfig(env); return config ? { genuineAiConfigured: true, provider: "OLLAMA_LOCAL", model: config.model, offlineMode: "SYNTHETIC_AI_DEMO", genuineAiStatus: "LOCAL_MODEL_READY_FOR_OPERATOR_INITIATED_INFERENCE" } : { genuineAiConfigured: false, offlineMode: "SYNTHETIC_AI_DEMO", genuineAiStatus: "NOT_CONFIGURED" }; } catch { return { genuineAiConfigured: false, offlineMode: "SYNTHETIC_AI_DEMO", genuineAiStatus: "CONFIGURATION_INVALID" }; } }
async function body(request: IncomingMessage): Promise<Json> { const chunks: Buffer[] = []; let size = 0; for await (const chunk of request) { const bytes = Buffer.from(chunk); size += bytes.length; if (size > 32_768) throw new Error("REQUEST_TOO_LARGE"); chunks.push(bytes); } const parsed: unknown = JSON.parse(Buffer.concat(chunks).toString("utf8") || "{}"); if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("JSON_OBJECT_REQUIRED"); return parsed as Json; }
function mode(input: Json | undefined): Mode { const value = optional(input, "mode") ?? "synthetic"; if (value !== "synthetic" && value !== "ollama") throw new Error("INVALID_AI_MODE: choose Offline Demo or Ollama Local AI"); return value; }
function text(input: Json | undefined, field: string): string { const value = optional(input, field); if (!value || value.length > 4_000) throw new Error(`${field.toUpperCase()}_REQUIRED_OR_TOO_LARGE`); return value; }
function optional(input: Json | undefined, field: string): string | undefined { const value = input?.[field]; return typeof value === "string" ? value.trim() : undefined; }
function id(path: string): string { const matched = path.match(/^\/api\/proposals\/([^/]+)\/(?:approve|reject|amend|sign|run|mismatch|payment-link|verify-payment-link|orders-payment-session|verify-orders-payment|authorise-orders-simulation|execute-orders-simulation)$/); if (!matched) throw new Error("INVALID_PROPOSAL_ROUTE"); return decodeURIComponent(matched[1]); }
function paymentLinkReturnUrl(environment: NodeJS.ProcessEnv): string { const value = environment.HBIEPA_SANDBOX_RETURN_URL ?? "https://example.com/hbiepa/sandbox-return"; try { if (new URL(value).protocol !== "https:") throw new Error(); return value; } catch { throw new Error("PAYPAL_SANDBOX_RETURN_URL_MUST_BE_HTTPS"); } }
function paymentLinkCancelUrl(environment: NodeJS.ProcessEnv): string { const value = environment.HBIEPA_SANDBOX_CANCEL_URL ?? "https://example.com/hbiepa/sandbox-cancel"; try { if (new URL(value).protocol !== "https:") throw new Error(); return value; } catch { throw new Error("PAYPAL_SANDBOX_CANCEL_URL_MUST_BE_HTTPS"); } }
function safe(error: unknown): string { const message = error instanceof Error ? error.message : "REQUEST_FAILED"; return /api.key|bearer|secret|private/i.test(message) ? "AI_PROVIDER_CONFIGURATION_FAILED" : message; }
function send(response: ServerResponse, code: number, payload: unknown) { response.writeHead(code, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }); response.end(JSON.stringify(payload)); }
function html(response: ServerResponse) { response.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }); response.end(renderedPage()); }
function paymentPage(response: ServerResponse, session: Readonly<{ amount: { currency: string; value: string }; expiresAt: string; checkoutPath: string; collectionType: string }>) { response.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "Referrer-Policy": "no-referrer", "X-Content-Type-Options": "nosniff" }); response.end(`<!doctype html><title>HBIEPA Sandbox Checkout</title><main><h1>PayPal Sandbox checkout</h1><p>Demonstration collection only — no remittance or payout.</p><p>Amount: ${session.amount.currency} ${session.amount.value}</p><p>Expires: ${session.expiresAt}</p><p><a href="${session.checkoutPath}">Continue to PayPal Sandbox Checkout</a></p><small>${session.collectionType}</small></main>`); }

